sql.if:
AND EXISTS (
    SELECT 1 FROM TB_LMS_SBJCT_ADM ADM
    WHERE ADM.SBJCT_ID = S.SBJCT_ID
      AND ADM.SBJCT_ADM_TYCD = 'PROF'
      AND ADM.USER_ID = #{userId}
)

mapper.sql:

    AND EXISTS (
        SELECT 1
        FROM TB_LMS_USER_AUTHRT UA_F
        WHERE UA_F.USER_ID = U.USER_ID
          AND UA_F.ORG_ID = #{orgId}
    )


    AND (
          EXISTS (
              SELECT 1
              FROM TB_LMS_SBJCT_ADM ADM
              WHERE ADM.SBJCT_ID = #{sbjctId}
                AND ADM.SBJCT_ADM_TYCD = 'PROF'
                AND ADM.USER_ID = U.USER_ID
          )
       OR EXISTS (
              SELECT 1
              FROM TB_LMS_ATNDLC A
              WHERE A.SBJCT_ID = #{sbjctId}
                AND A.USER_ID = U.USER_ID
          )
    )


    AND U.USER_TYCD = #{userTycd}



        AND U.USERNM LIKE FN_LIKE_VAL(#{searchText})




        AND U.STDNT_NO LIKE FN_LIKE_VAL(#{searchText})


AND U.USER_TYCD <> 'ADM'

mapper.select:
/* SQL ID : MsgRcptnAgreDAO.selectRcptnAgreList 설 명 : 알림수신동의 목록 조회 (교수) */ SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY SBJCT_YR DESC NULLS LAST, SBJCT_SMSTR ASC NULLS LAST, SBJCTNM ASC NULLS LAST, USERNM ASC) AS LINE_NO , COUNT(*) OVER () AS TOTAL_CNT , INNERQ.* FROM ( SELECT
UNION ALL
) INNERQ ) WHERE LINE_NO BETWEEN #{firstIndex} AND #{lastIndex} ORDER BY LINE_NO

